import { memo, useCallback, useEffect } from 'react';

import { useRoute } from '@react-navigation/core';
import { useIntl } from 'react-intl';

import { Alert, Page, Stack } from '@onekeyhq/components';
import backgroundApiProxy from '@onekeyhq/kit/src/background/instance/backgroundApiProxy';
import useDappApproveAction from '@onekeyhq/kit/src/hooks/useDappApproveAction';
import { usePromiseResult } from '@onekeyhq/kit/src/hooks/usePromiseResult';
import {
  usePreCheckTxStatusAtom,
  useSendConfirmActions,
  useSendFeeStatusAtom,
  useSendTxStatusAtom,
} from '@onekeyhq/kit/src/states/jotai/contexts/sendConfirm';
import { useInscriptionProtectionStateAtom } from '@onekeyhq/kit-bg/src/states/jotai/atoms';
import {
  EAppEventBusNames,
  appEventBus,
} from '@onekeyhq/shared/src/eventBus/appEventBus';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import type {
  EModalSendRoutes,
  IModalSendParamList,
} from '@onekeyhq/shared/src/routes';
import { EDAppModalPageStatus } from '@onekeyhq/shared/types/dappConnection';
import { ESendFeeStatus } from '@onekeyhq/shared/types/fee';
import { ESendPreCheckTimingEnum } from '@onekeyhq/shared/types/send';

import { SendConfirmProviderMirror } from '../../components/SendConfirmProvider/SendConfirmProviderMirror';
import { SendTestIDs } from '../../testIDs';

import SendConfirmActionsContainer from './SendConfirmActionsContainer';
import TxActionsContainer from './TxActionsContainer';
import { TxAdvancedSettingsContainer } from './TxAdvancedSettingsContainer';
import { TxSourceInfoContainer } from './TxSourceInfoContainer';
import { TxSpecialInfoContainer } from './TxSpecialInfoContainer';

import type { RouteProp } from '@react-navigation/core';

// TODO(6.7.0): Remove this legacy SendModal confirmation page.
// Current send confirmations go through SignatureConfirmModal -> TxConfirm;
// debug confirmation issues in the TxConfirm page instead.
function SendConfirmContainer() {
  const intl = useIntl();
  const route =
    useRoute<RouteProp<IModalSendParamList, EModalSendRoutes.SendConfirm>>();
  const {
    updateUnsignedTxs,
    updateNativeTokenInfo,
    updateSendFeeStatus,
    updatePreCheckTxStatus,
  } = useSendConfirmActions().current;
  const [inscriptionProtectionState] = useInscriptionProtectionStateAtom();
  const [sendFeeStatus] = useSendFeeStatusAtom();
  const [sendAlertStatus] = useSendTxStatusAtom();
  const [preCheckTxStatus] = usePreCheckTxStatusAtom();
  const {
    accountId,
    networkId,
    unsignedTxs,
    onSuccess,
    onFail,
    onCancel,
    sourceInfo,
    signOnly,
    useFeeInTx,
    transferPayload,
    feeInfoEditable,
    popStack,
  } = route.params;

  const dappApprove = useDappApproveAction({
    id: sourceInfo?.id ?? '',
    closeWindowAfterResolved: true,
  });

  useEffect(() => {
    appEventBus.emit(
      EAppEventBusNames.SignatureConfirmContainerMounted,
      undefined,
    );
  }, []);

  const { network } =
    usePromiseResult(
      async () => {
        updateUnsignedTxs(unsignedTxs);
        updateNativeTokenInfo({
          isLoading: true,
          balance: '0',
          logoURI: '',
          info: undefined,
        });
        const [n, nativeTokenAddress] = await Promise.all([
          backgroundApiProxy.serviceNetwork.getNetwork({ networkId }),
          backgroundApiProxy.serviceToken.getNativeTokenAddress({ networkId }),
        ]);
        const withCheckInscription =
          await backgroundApiProxy.serviceSetting.getEffectiveInscriptionProtection(
            {
              networkId,
              accountId,
            },
          );
        const r = await backgroundApiProxy.serviceToken.fetchTokensDetails({
          networkId,
          accountId,
          contractList: [nativeTokenAddress],
          withFrozenBalance: true,
          withCheckInscription,
        });
        const balance = r[0].balanceParsed;
        updateNativeTokenInfo({
          isLoading: false,
          balance,
          logoURI: r[0].info.logoURI ?? '',
          info: r[0].info,
        });
        return { network: n };
      },
      // The policy state is an intentional invalidation signal; bg computes the final value.
      // oxlint-disable-next-line react-hooks/exhaustive-deps
      [
        accountId,
        networkId,
        unsignedTxs,
        updateNativeTokenInfo,
        updateUnsignedTxs,
        inscriptionProtectionState.localEnabled,
        inscriptionProtectionState.serverEnabled,
      ],
    ).result ?? {};

  usePromiseResult(async () => {
    try {
      await backgroundApiProxy.serviceSend.precheckUnsignedTxs({
        networkId,
        accountId,
        unsignedTxs,
        precheckTiming: ESendPreCheckTimingEnum.BeforeTransaction,
      });
    } catch (e: any) {
      updatePreCheckTxStatus((e as Error).message);
    }
  }, [accountId, networkId, unsignedTxs, updatePreCheckTxStatus]);

  useEffect(
    () => () =>
      updateSendFeeStatus({ status: ESendFeeStatus.Idle, errMessage: '' }),
    [updateSendFeeStatus],
  );

  const renderSendConfirmView = useCallback(
    () => (
      <>
        <Page.Body testID={SendTestIDs.confirmPage}>
          <Stack>
            {sendFeeStatus.errMessage ? (
              <Alert
                mb="$2.5"
                fullBleed
                icon="ErrorOutline"
                type="critical"
                title={sendFeeStatus.errMessage}
                action={{
                  primary: intl.formatMessage({
                    id: ETranslations.global_retry,
                  }),
                  isPrimaryLoading:
                    sendFeeStatus.status === ESendFeeStatus.Loading,
                  onPrimaryPress() {
                    appEventBus.emit(
                      EAppEventBusNames.EstimateTxFeeRetry,
                      undefined,
                    );
                  },
                }}
              />
            ) : null}
            {sendAlertStatus.isInsufficientNativeBalance ? (
              <Alert
                mb="$2.5"
                fullBleed
                icon="ErrorOutline"
                type="critical"
                title={intl.formatMessage(
                  {
                    id: ETranslations.msg__str_is_required_for_network_fees_top_up_str_to_make_tx,
                  },
                  {
                    crypto: network?.symbol ?? '',
                  },
                )}
              />
            ) : null}
            {preCheckTxStatus.errorMessage ? (
              <Alert
                mb="$2.5"
                fullBleed
                icon="ErrorOutline"
                type="critical"
                title={preCheckTxStatus.errorMessage}
              />
            ) : null}
          </Stack>
          <TxSourceInfoContainer sourceInfo={sourceInfo} />
          <TxActionsContainer
            accountId={accountId}
            networkId={networkId}
            transferPayload={transferPayload}
          />
          <TxSpecialInfoContainer
            accountId={accountId}
            networkId={networkId}
            unsignedTxs={unsignedTxs}
          />
          <TxAdvancedSettingsContainer
            accountId={accountId}
            networkId={networkId}
          />
        </Page.Body>
        <SendConfirmActionsContainer
          popStack={popStack}
          sourceInfo={sourceInfo}
          signOnly={signOnly}
          accountId={accountId}
          networkId={networkId}
          onSuccess={onSuccess}
          onFail={onFail}
          onCancel={onCancel}
          transferPayload={transferPayload}
          useFeeInTx={useFeeInTx}
          feeInfoEditable={feeInfoEditable}
        />
      </>
    ),
    [
      sendFeeStatus.errMessage,
      sendFeeStatus.status,
      intl,
      sendAlertStatus.isInsufficientNativeBalance,
      network?.symbol,
      preCheckTxStatus.errorMessage,
      sourceInfo,
      accountId,
      networkId,
      transferPayload,
      unsignedTxs,
      popStack,
      signOnly,
      onSuccess,
      onFail,
      onCancel,
      useFeeInTx,
      feeInfoEditable,
    ],
  );

  const handleOnClose = (extra?: { flag?: string }) => {
    if (extra?.flag !== EDAppModalPageStatus.Confirmed) {
      dappApprove.reject();
    }
  };

  const pageTitleTranslationId = transferPayload?.isPrivateSend
    ? ETranslations.private_send_private_send
    : ETranslations.transaction__transaction_confirm;

  return (
    <Page scrollEnabled onClose={handleOnClose} safeAreaEnabled>
      <Page.Header
        title={intl.formatMessage({
          id: pageTitleTranslationId,
        })}
      />
      {renderSendConfirmView()}
    </Page>
  );
}

const SendConfirmContainerWithProvider = memo(() => (
  <SendConfirmProviderMirror>
    <SendConfirmContainer />
  </SendConfirmProviderMirror>
));
SendConfirmContainerWithProvider.displayName =
  'SendConfirmContainerWithProvider';

export { SendConfirmContainer, SendConfirmContainerWithProvider };
